package com.shipflow.tracking.application;
import com.shipflow.order.application.ShipmentOrderException;import com.shipflow.tracking.api.model.*;import com.shipflow.tracking.domain.TrackingEvent;import com.shipflow.tracking.mapper.TrackingQueryMapper;import org.springframework.stereotype.Service;import java.time.ZoneOffset;import java.util.*;
/** Read-only tenant-scoped tracking projections; no callback or event mutation occurs here. */
@Service public class TrackingQueryApplicationService{private final TrackingQueryMapper mapper;public TrackingQueryApplicationService(TrackingQueryMapper mapper){this.mapper=mapper;}public List<TrackingEventResponse> list(Long tenantId,Long orderId){require(tenantId,orderId);return mapper.findEvents(tenantId,orderId).stream().map(this::response).toList();}public TrackingStatusResponse status(Long tenantId,Long orderId){require(tenantId,orderId);TrackingEvent latest=mapper.findLatest(tenantId,orderId);return new TrackingStatusResponse(orderId,mapper.currentStatus(tenantId,orderId),latest==null?null:response(latest));}private void require(Long tenant,Long order){if(tenant==null||tenant<1)throw new ShipmentOrderException("COMMON-1004",403);if(order==null||!mapper.orderExists(tenant,order))throw new ShipmentOrderException("COMMON-1006",404);}private TrackingEventResponse response(TrackingEvent e){return new TrackingEventResponse(e.id(),e.trackingNo(),e.eventCode(),e.description(),e.eventTime().atOffset(ZoneOffset.UTC),e.processStatus());}}
